    ('App\\Entity\\ProjectParent', 3, 'Projet Parent 3 - Nouvelle ère', 'Le Projet Parent 3 entame une nouvelle phase',
     'Le Projet Parent 3 représente une transformation majeure pour notre organisation. Nous nous concentrons sur l\'intégration des nouvelles technologies pour améliorer l\'efficacité et la durabilité.', 'system', NOW()),
    ('App\\Entity\\ProjectChild', 3, 'Sous-Projet 3.1 - Recherche et développement',
     'Sous-Projet 3.1 : recherche et développement de nouvelles solutions',
     'Sous-Projet 3.1 est centré sur la recherche pour découvrir de nouvelles solutions technologiques. Les chercheurs travailleront sur des innovations qui changeront la donne dans notre secteur.', 'system', NOW()),
    ('App\\Entity\\ProjectParent', 4, 'Expansion du Projet Parent 4',
